# scan 172.26.0.0/24 faster with threading
import socket, concurrent.futures

def check(ip, port):
    s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    s.settimeout(0.2)
    try:
        if s.connect_ex((ip, port)) == 0:
            return (ip, port)
    except:
        pass
    finally:
        s.close()
    return None

with concurrent.futures.ThreadPoolExecutor(max_workers=50) as ex:
    futs = [ex.submit(check, f"172.26.0.{i}", p) for i in range(1, 20) for p in [80, 8080, 5000, 3000, 53]]
    for f in concurrent.futures.as_completed(futs):
        r = f.result()
        if r:
            print("Found:", r)
'"}

