# scan all ports on 172.26.0.3
import socket, concurrent.futures

def scan(port):
    s = socket.socket()
    s.settimeout(0.1)
    if s.connect_ex(("172.26.0.3", port)) == 0:
        return port
    s.close()
    return None

with concurrent.futures.ThreadPoolExecutor(max_workers=100) as ex:
    for p in ex.map(scan, range(1, 10000)):
        if p:
            print("Port open on 172.26.0.3:", p)
